import{_ as s,o as n,c as t,a2 as o}from"./chunks/framework.BM5YPQmL.js";const g=JSON.parse('{"title":"ADR-013: Assisted cue alignment","description":"","frontmatter":{},"headers":[],"relativePath":"adr/013-assisted-cue-alignment.md","filePath":"adr/013-assisted-cue-alignment.md"}'),a={name:"adr/013-assisted-cue-alignment.md"};function i(r,e,d,l,c,u){return n(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="adr-013-assisted-cue-alignment" tabindex="-1">ADR-013: Assisted cue alignment <a class="header-anchor" href="#adr-013-assisted-cue-alignment" aria-label="Permalink to &quot;ADR-013: Assisted cue alignment&quot;">​</a></h1><ul><li>Status: accepted · Date: 2026-11-01 · Supersedes ADR-004 in part</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>ADR-004 chose human-marked cues: the author presses Space at the start of each line. It works, but it is the slowest step for long episodes, and most of it is mechanical: the script is already known, so the recording only has to be split into the lines and words that are written down. ADR-004&#39;s reason for avoiding speech recognition was that the render engine must contain no AI/ML (G3) and that timing must survive re-recording one sentence. Neither requires the cues themselves to be hand-made.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Cues may be <strong>suggested by the machine</strong> and then checked by ear. Suggested cues are an authoring aid only:</p><ol><li><strong>Engines</strong> (<code>@reelforge/assist</code>, <code>reelforge align</code>, the editor&#39;s <em>Auto-mark from voice</em>, MCP <code>align_cues</code>): <ul><li><strong>DSP</strong> (always available, no model): an energy/pause analysis and a dynamic-programming split of the recording into the script&#39;s lines weighted by syllables; words by syllables, punctuation and energy valleys (<code>packages/audio/src/align.ts</code>).</li><li><strong>Silero VAD</strong> (optional): a speech/non-speech gate so music beds and room noise do not create false pauses.</li><li><strong>Whisper word timings</strong> (optional): the recognizer&#39;s word <em>timings</em> are matched to the known script by fuzzy DTW. Its transcript is discarded, so recognition errors do not reach the video.</li></ul></li><li>Suggested cues are written to <code>cues.json</code> with <strong><code>auto: true</code></strong> (V-3 info until a person saves them in Cues mode, which clears the flag).</li><li>They <strong>never overwrite cues a person marked</strong> unless the person confirms (<code>--force</code>, a dialog in the editor; the editor&#39;s write is one undo step).</li><li>Models are <strong>never used at render time</strong>. The renderer reads <code>cues.json</code> like any other cues file, so rendering stays deterministic and offline (ADR-003). The optional models are downloaded once by <code>reelforge align --setup</code>, pinned to a revision and checked by SHA-256 (see <code>packages/assist/runtime/README.md</code>); after that, alignment also runs offline.</li></ol><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Marking a long episode becomes &quot;align, listen once, fix the amber lines&quot;.</li><li>ADR-004 still holds for the manual workflow and for the guarantee that animations follow lines and words, not seconds.</li><li>Accuracy is measured, not assumed: <code>node scripts/eval-align.mjs</code> and <code>scripts/eval-assist.mjs</code> run against recordings with known word timings (<code>fixtures/align/</code>). An Arabic fixture recorded by a person is scaffolded in <code>fixtures/align/ar-real/</code>.</li><li>The project no longer claims &quot;no AI&quot; without qualification: the render engine contains none, and the optional authoring helpers are local and opt-in.</li></ul>',9)])])}const m=s(a,[["render",i]]);export{g as __pageData,m as default};
